/* ══════════════════════════════════════════════════════════════
   누제믹 챗봇 런처

   메인 페이지에 이 한 줄만 넣으면 오른쪽 아래에 모루믹이 나타납니다.

     <script src="nj-widget.js" defer
             data-store="main"      main | yeonbang  (주소의 ?store= 가 우선)
             data-mode="overlay"    overlay 배경없이 위에 | panel 흰 판 | page 페이지이동
             data-chat="chat.html"
             data-custom="custom.html"

   메인 페이지에 이 파일을 통째로 붙여 넣을 때는
   앞에 window.NJ_WIDGET = { store:'main', mode:'panel' } 로 설정합니다.

   챗봇은 눌렀을 때 처음 만들어집니다.
   메인 페이지 로딩에는 이 파일(몇 KB)만 얹힙니다.
   ══════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  if (window.__njWidget) return;
  window.__njWidget = true;

  var me  = document.currentScript
          || (function(){ var s=document.getElementsByTagName('script'); return s[s.length-1]; })();
  var cfg = window.NJ_WIDGET || {};
  function opt(k, d){
    if (cfg[k]) return cfg[k];
    var v = me && me.getAttribute && me.getAttribute('data-' + k.toLowerCase());
    return v || d;
  }
  var CHAT   = opt('chat',   'chat.html');
  var CUSTOM = opt('custom', 'custom.html');
  var MODE  = opt('mode',  'overlay');   // overlay 배경없이 위에 | panel 흰 판 | page 페이지이동
  var LANG  = opt('lang',  '');
  var LABEL = opt('label', {ko:'무엇이든 물어보세요',en:'Ask me anything',cn:'有问题尽管问我',jp:'なんでも聞いてね'}[LANG] || '무엇이든 물어보세요');
  /* 상품 상세 페이지처럼 이미 자체 챗봇 버튼(FAB)이 있는 화면에서는
     data-button="0" 또는 NJ_WIDGET={button:'0'} 로 이 위젯의 버튼 생성을 꺼둡니다.
     이때도 window.njChat.open()/close() 와 패널 동작은 그대로 씁니다. */
  var SHOW_BTN = opt('button', '1') !== '0';
  /* 모든 페이지에서 같은 투명 얼굴 아이콘을 씁니다. data-icon으로 별도 지정도 가능합니다. */
  var ICON = opt('icon', 'data:image/webp;base64,');
  var defaultIcon = ICON === 'data:image/webp;base64,';

  /* 매장은 메인 페이지 주소에서 먼저 찾습니다 (QR 이 ?store= 를 달고 들어옵니다) */
  var urlStore = new URLSearchParams(location.search).get('store');
  var STORE = (urlStore === 'main' || urlStore === 'yeonbang')
            ? urlStore : opt('store', 'main');

  var PINK = '#F56598', INK = '#141414';

  var css = ''
  + '.njw-btn{position:fixed;right:18px;bottom:calc(18px + env(safe-area-inset-bottom));z-index:2147483000;'
  +   'width:62px;height:62px;border-radius:50%;border:none;padding:0;cursor:pointer;'
  +   'background:#fff;box-shadow:0 4px 10px rgba(20,30,45,.10),0 12px 30px rgba(20,30,45,.16);'
  +   'display:flex;align-items:center;justify-content:center;'
  +   'transition:transform .18s cubic-bezier(.2,.9,.3,1.3);'
  +   'animation:njwFloat 3.6s ease-in-out infinite}'
  + '.njw-btn:hover{transform:translateY(-3px)}'
  + '.njw-btn:active{transform:scale(.9)}'
  + '.njw-btn:focus-visible{outline:3px solid '+PINK+';outline-offset:3px}'
  + '.njw-btn svg{width:44px;height:44px;display:block;pointer-events:none}'
  + '@keyframes njwFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}'
  + '.njw-dot{position:absolute;top:2px;right:2px;width:13px;height:13px;border-radius:50%;'
  +   'background:'+PINK+';border:2.5px solid #fff}'

  + '.njw-tip{position:fixed;right:88px;bottom:calc(34px + env(safe-area-inset-bottom));z-index:2147482999;'
  +   'background:#fff;color:'+INK+';font-size:13px;line-height:1.4;font-weight:500;'
  +   'padding:9px 14px;border-radius:999px;white-space:nowrap;'
  +   'box-shadow:0 3px 8px rgba(20,30,45,.10),0 10px 24px rgba(20,30,45,.13);'
  +   'opacity:0;transform:translateX(8px);transition:opacity .3s,transform .3s;pointer-events:none}'
  + '.njw-tip.on{opacity:1;transform:none}'

  + '.njw-dim{position:fixed;top:0;right:0;bottom:0;left:0;z-index:2147483100;'
  +   'background:rgba(20,20,20,.34);opacity:0;visibility:hidden;pointer-events:none;'
  +   'transition:opacity .3s,visibility .3s}'
  + '.njw-dim.on{opacity:1;visibility:visible;pointer-events:auto}'
  + '.njw-dim.soft{background:rgba(20,20,20,.2)}'

  /* 챗봇 패널 — 오른쪽 아래. 화면을 다 덮지 않습니다. */
  + '.njw-panel{position:fixed;z-index:2147483200;overflow:hidden;'
  +   'right:20px;bottom:20px;width:400px;height:min(660px,calc(100dvh - 40px));'
  +   'border-radius:24px;'
  /* 닫힌 패널은 투명하기만 하면 화면을 덮은 채 터치를 가로채서 뒤 페이지 버튼이 안 눌림 —
     닫히면 visibility:hidden + pointer-events:none (사라지는 애니메이션이 끝난 뒤 숨김) */
  +   'transform:translateY(14px) scale(.975);opacity:0;visibility:hidden;pointer-events:none;'
  +   'transition:transform .32s cubic-bezier(.2,.9,.3,1.05),opacity .24s,visibility 0s linear .32s}'
  + '.njw-panel.on{transform:none;opacity:1;visibility:visible;pointer-events:auto;'
  +   'transition:transform .32s cubic-bezier(.2,.9,.3,1.05),opacity .24s,visibility 0s}'
  + '.njw-panel iframe{width:100%;height:100%;border:0;display:block;background:transparent}'
  /* 어두운 유리 — 뒤 페이지를 패널 자리에서만 흐리게 합니다 */
  + '.njw-panel.glass{background:rgba(20,20,24,.55);'
  +   '-webkit-backdrop-filter:blur(24px) saturate(.7) brightness(.7);'
  +   'backdrop-filter:blur(24px) saturate(.7) brightness(.7);'
  +   'box-shadow:0 10px 24px rgba(0,0,0,.28),0 30px 70px rgba(0,0,0,.34)}'
  /* 흰 판 */
  + '.njw-panel.panel{background:#F6F5F2;'
  +   'box-shadow:0 8px 20px rgba(20,30,45,.14),0 26px 60px rgba(20,30,45,.24)}'
  + '@media(max-width:560px){.njw-panel{right:0;left:0;bottom:0;width:auto;'
  +   'height:86dvh;border-radius:22px 22px 0 0}}'

  + '@media(prefers-reduced-motion:reduce){.njw-btn{animation:none}'
  +   '.njw-panel,.njw-tip,.njw-dim{transition:none}}';

  if(defaultIcon && !document.querySelector('link[href^="nj-character.css"]')){
    var characterStyle=document.createElement('link'); characterStyle.rel='stylesheet'; characterStyle.href='nj-character.css?v=20261001-frequent-motion'; document.head.appendChild(characterStyle);
  }
  var st = document.createElement('style');
  st.textContent = css;
  document.head.appendChild(st);

  /* 런처 인형 — 사진 대신 가벼운 벡터를 씁니다 */
  function doll(){
    var pts=[], n=13, r=19, cx=24, cy=25;
    for(var i=0;i<n*2;i++){
      var a=i*Math.PI/n, rr=(i%2===0)?r:r*0.79;
      pts.push((cx+rr*Math.cos(a)).toFixed(1)+','+(cy+rr*Math.sin(a)).toFixed(1));
    }
    return '<svg viewBox="0 0 48 48" aria-hidden="true">'
      + '<circle cx="24" cy="7.5" r="5.2" fill="none" stroke="#2FA79F" stroke-width="2.4"/>'
      + '<polygon fill="#F0E4CE" points="'+pts.join(' ')+'"/>'
      + '<ellipse cx="19" cy="23.5" rx="2.5" ry="2.9" fill="#141414"/>'
      + '<ellipse cx="29" cy="23.5" rx="2.5" ry="2.9" fill="#141414"/>'
      + '<circle cx="19.9" cy="22.4" r="1" fill="#fff"/><circle cx="29.9" cy="22.4" r="1" fill="#fff"/>'
      + '<ellipse cx="14.5" cy="29" rx="3.1" ry="2" fill="#FF7EA8" opacity=".5"/>'
      + '<ellipse cx="33.5" cy="29" rx="3.1" ry="2" fill="#FF7EA8" opacity=".5"/>'
      + '<path d="M21.4 29.4 Q24 32 26.6 29.4" fill="none" stroke="#6B4A33"'
      +   ' stroke-width="1.5" stroke-linecap="round" opacity=".8"/></svg>';
  }

  var btn = null, tip = null;
  if (SHOW_BTN){
    btn = document.createElement('button');
    btn.className = 'njw-btn' + (defaultIcon ? ' nj-character-launcher' : '');
    btn.type = 'button';
    btn.setAttribute('aria-label', LABEL);
    var face = ICON
      ? '<img class="'+(defaultIcon?'nj-character-face':'')+'" src="'+ICON+'" alt="" style="width:100%;height:100%;object-fit:'+(defaultIcon?'contain':'cover')+';border-radius:'+(defaultIcon?'0':'50%')+';display:block">'
      : doll();
    btn.innerHTML = face + (defaultIcon ? '' : '<span class="njw-dot"></span>');
    document.body.appendChild(btn);

  }

  var pageFrame=document.querySelector('#screen');
  function visibleBounds(){
    var r=pageFrame ? pageFrame.getBoundingClientRect() : {left:0,right:innerWidth,top:0,bottom:innerHeight};
    return {left:Math.max(0,r.left),right:Math.min(innerWidth,r.right),top:Math.max(0,r.top),bottom:Math.min(innerHeight,r.bottom)};
  }
  function positionLauncher(){
    if(!btn || !pageFrame || open)return;
    var bounds=visibleBounds(), width=btn.offsetWidth, height=btn.offsetHeight;
    var fits=bounds.right-bounds.left>=width+36 && bounds.bottom-bounds.top>=height+36;
    btn.style.visibility=fits?'':'hidden';
    btn.style.right=Math.max(18,innerWidth-bounds.right+18)+'px';
    btn.style.bottom=Math.max(18,innerHeight-bounds.bottom+18)+'px';
  }
  if(btn && pageFrame){
    var positionFrame=0;
    var queuePosition=function(){if(!positionFrame)positionFrame=requestAnimationFrame(function(){positionFrame=0;positionLauncher();});};
    window.addEventListener('resize',queuePosition,{passive:true});
    document.addEventListener('scroll',queuePosition,{passive:true,capture:true});
    if(window.visualViewport){visualViewport.addEventListener('resize',queuePosition);visualViewport.addEventListener('scroll',queuePosition);}
    var frameObserver=new ResizeObserver(queuePosition);frameObserver.observe(pageFrame);frameObserver.observe(btn);
    positionLauncher();
  }

  // Both the shared launcher and existing product-page buttons use the same quiet hint.
  var tipAnchor = btn || document.querySelector('.fab.nj-character-launcher');
  var tipTimer = 0, tipHideTimer = 0, tipIndex = 0;
  var tipMessages = {
    ko:['필요한 게 있으세요?', '궁금한 게 있으면 물어보세요'],
    en:['Need a hand?', 'Any questions? I’m here.'],
    cn:['有什么需要帮忙的吗？', '有问题可以问我哦'],
    jp:['何かお困りですか？', '気になることがあれば聞いてね']
  };
  var customTip = cfg.label || (me && me.getAttribute('data-label'));
  var messages = customTip ? [customTip] : (tipMessages[LANG] || tipMessages.ko);
  function tipDelay(){ return 40000 + Math.random()*15000; }
  function hideTip(){
    clearTimeout(tipTimer); clearTimeout(tipHideTimer);
    if(tip) tip.classList.remove('on');
  }
  function queueTip(delay){
    hideTip();
    if(tip && !open && !document.hidden) tipTimer=setTimeout(showTip,delay);
  }
  function showTip(){
    if(!tip || open || document.hidden) return;
    positionLauncher();
    var bounds=visibleBounds();
    var r=tipAnchor.getBoundingClientRect();
    if(!r.width || !r.height || r.bottom<=bounds.top || r.top>=bounds.bottom || r.right<=bounds.left || r.left>=bounds.right || getComputedStyle(tipAnchor).visibility==='hidden'){
      queueTip(tipDelay()); return;
    }
    tip.textContent=messages[tipIndex++ % messages.length];
    tip.style.maxWidth=Math.max(0,bounds.right-bounds.left-24)+'px';
    tip.style.whiteSpace='normal';
    tip.style.right='auto'; tip.style.bottom='auto';
    var width=tip.offsetWidth, height=tip.offsetHeight;
    var left=r.left-width-10, top=r.top+(r.height-height)/2;
    if(left<bounds.left+12){ left=r.left+r.width/2-width/2; top=r.top-height-10; }
    tip.style.left=Math.max(bounds.left+12,Math.min(left,bounds.right-width-12))+'px';
    tip.style.top=Math.max(bounds.top+12,Math.min(top,bounds.bottom-height-12))+'px';
    tip.classList.add('on');
    tipHideTimer=setTimeout(function(){
      tip.classList.remove('on');
      tipTimer=setTimeout(showTip,tipDelay());
    },4500);
  }
  if(tipAnchor){
    tip=document.createElement('div'); tip.className='njw-tip';
    tip.setAttribute('aria-hidden','true'); document.body.appendChild(tip);
    // Interactions postpone the next hint; opening the chatbot never shows one behind it.
    var onActivity=function(){ queueTip(tipDelay()); };
    document.addEventListener('pointerdown',onActivity,{passive:true});
    document.addEventListener('keydown',onActivity);
    document.addEventListener('scroll',onActivity,{passive:true,capture:true});
    window.addEventListener('resize',onActivity);
    document.addEventListener('visibilitychange',onActivity);
    window.addEventListener('pagehide',hideTip);
    window.addEventListener('pageshow',function(e){if(e.persisted)onActivity();});
    queueTip(4000);
  }

  function chatURL(){
    var u = CHAT + (CHAT.indexOf('?') < 0 ? '?' : '&') + 'store=' + encodeURIComponent(STORE);
    if (LANG) u += '&lang=' + encodeURIComponent(LANG);
    u += '&ui=' + (MODE === 'panel' ? 'panel' : 'overlay');
    u += '&custom=' + encodeURIComponent(CUSTOM);
    return u;
  }

  var panel = null, dim = null, open = false;

  function openChat(){
    if (MODE === 'page'){ location.href = chatURL(); return; }
    if (open) return;
    open = true;
    try{ if (window.gtag) window.gtag('event', 'chatbot_open', { from: (location.pathname.split('/').pop() || 'index.html').replace(/\.html?$/, '') }); }catch(_){}
    hideTip();
    if (btn) btn.style.display = 'none';

    if (!panel){
      dim = document.createElement('div');
      dim.className = 'njw-dim' + (MODE === 'panel' ? '' : ' soft');
      dim.addEventListener('click', closeChat);
      document.body.appendChild(dim);

      panel = document.createElement('div');
      panel.className = 'njw-panel ' + (MODE === 'panel' ? 'panel' : 'glass');
      panel.setAttribute('role', 'dialog');
      panel.setAttribute('aria-label', '누제믹 안내');
      var f = document.createElement('iframe');
      f.src = chatURL();
      f.title = '누제믹 안내';
      f.setAttribute('allow', 'clipboard-write');
      panel.appendChild(f);
      document.body.appendChild(panel);
    }
    requestAnimationFrame(function(){
      dim.classList.add('on');
      panel.classList.add('on');
    });
  }

  function closeChat(){
    if (!open) return;
    open = false;
    try{ if(window.gtag) window.gtag('event', 'chatbot_close'); }catch(_){}
    panel.classList.remove('on');
    dim.classList.remove('on');
    if (btn) btn.style.display = '';
    positionLauncher();
    queueTip(tipDelay());
  }

  if (btn) btn.addEventListener('click', openChat);

  /* 챗봇 안에서 오는 신호 */
  window.addEventListener('message', function(e){
    if (!e.data) return;
    if (e.data.type === 'nj:close') closeChat();
    /* "커스텀 만들러 가기" — 챗봇을 닫고 커스텀 화면으로 이동합니다 */
    if (e.data.type === 'nj:custom'){
      closeChat();
      location.href = e.data.url || CUSTOM;
    }
  });
  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape') closeChat();
  });

  window.njChat = { open: openChat, close: closeChat };
})();
